import requests
qs=['"bifunctional shikimate dehydrogenase/shikimate kinase"','"shikimate dehydrogenase-kinase"','"shikimate dehydrogenase kinase"','"quinate dehydrogenase kinase"','"shikimate dehydrogenase and shikimate kinase"']
for q in qs:
 p={'db':'protein','term':q+'[Title]','retmode':'json','retmax':20}
 j=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi',params=p,timeout=30).json()
 ids=j['esearchresult']['idlist']; print(q,ids)
 if ids:
  x=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'protein','id':','.join(ids),'retmode':'json'},timeout=30).json()
  for i in ids: print(x['result'][i].get('title'),x['result'][i].get('accessionversion'))

